#include <stdio.h>
#include <stdbool.h>
int main() {
    bool data_ready = false;
    int polls = 0;
    while (!data_ready) {
        // simulate reading a status register
        polls++;
        if (polls == 5) data_ready = true; // data arrives after 5 polls
    }
    printf("Polling finished after %d polls\n", polls);
    return 0;
}

